(function () {
  'use strict';


  function ensureScroller(table) {
    if (!table || !table.parentNode) return null;
    var parent = table.parentElement;
    var wrapper = parent && parent.matches && parent.matches('.wp-block-table, .go-table-scroll') ? parent : null;
    if (!wrapper) {
      wrapper = document.createElement('div');
      wrapper.className = 'go-table-scroll go-table-scroll--runtime';
      table.parentNode.insertBefore(wrapper, table);
      wrapper.appendChild(table);
    }
    if (wrapper.dataset.goTableScrollReady !== '1') {
      wrapper.dataset.goTableScrollReady = '1';
      wrapper.scrollLeft = 0;
      var touched = function () { wrapper.dataset.goTableTouched = '1'; };
      wrapper.addEventListener('pointerdown', touched, { passive: true, once: true });
      wrapper.addEventListener('touchstart', touched, { passive: true, once: true });
      requestAnimationFrame(function () { if (wrapper.dataset.goTableTouched !== '1') wrapper.scrollLeft = 0; });
    }
    return wrapper;
  }

  function normalizeTable(table) {
    if (!table || table.dataset.goTableNormalized === '1') return;
    var provider = '.google-auto-placed,ins.adsbygoogle,[data-go-ad-placement],.go-article-ad,[id^="aswift_"],[id^="google_ads_"]';
    if (table.closest(provider) || table.querySelector(provider)) return;
    table.dataset.goTableNormalized = '1';
    table.classList.add('go-editorial-table');
    ensureScroller(table);

    var firstRow = table.querySelector('tr');
    var hasHead = !!table.querySelector('thead');
    if (!hasHead && firstRow) {
      var cells = Array.prototype.slice.call(firstRow.children).filter(function (cell) {
        return /^(TD|TH)$/i.test(cell.tagName || '');
      });
      var looksLikeHeader = cells.length >= 2 && cells.every(function (cell) {
        var text = (cell.textContent || '').trim();
        if (!text) return false;
        return !!cell.querySelector('strong, b') || /^(TH)$/i.test(cell.tagName || '');
      });
      if (looksLikeHeader) {
        table.classList.add('go-table--promoted-header');
        cells.forEach(function (cell) {
          cell.setAttribute('role', 'columnheader');
          cell.setAttribute('scope', 'col');
        });
      }
    }

    var columnCount = firstRow ? firstRow.children.length : 0;
    if (columnCount > 0) table.style.setProperty('--go-table-columns', String(columnCount));
  }

  function normalizeAll(root) {
    var scope = root && root.querySelectorAll ? root : document;
    var tableSelector = scope === document ? '.entry-content.go-single__content table' : 'table';
    Array.prototype.slice.call(scope.querySelectorAll(tableSelector)).forEach(normalizeTable);
  }

  function boot() {
    var article = document.querySelector('.entry-content.go-single__content');
    if (!article) return;
    normalizeAll(article);
    if (!('MutationObserver' in window)) return;
    var observer = new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        Array.prototype.forEach.call(mutation.addedNodes || [], function (node) {
          if (node.nodeType !== 1) return;
          if (node.matches && node.matches('table')) normalizeTable(node);
          normalizeAll(node);
        });
      });
    });
    observer.observe(article, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true });
  else boot();
})();
